using UnityEngine;

/// <summary>
/// Central game manager for Tales of the Tao.
/// Handles initialization, global state, and high‑level game flow.
/// </summary>
public class GameManager : MonoBehaviour
{
    // Singleton instance for easy access
    public static GameManager Instance { get; private set; }

    // Example of a global game state variable
    public bool IsGamePaused { get; private set; } = false;

    void Awake()
    {
        // Enforce singleton pattern
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject);
    }

    void Start()
    {
        InitializeGame();
    }

    private void InitializeGame()
    {
        // TODO: Load initial data, set up managers, etc.
        Debug.Log("[GameManager] Game initialized.");
    }

    public void PauseGame()
    {
        if (IsGamePaused) return;
        IsGamePaused = true;
        Time.timeScale = 0f;
        // Additional pause logic here
        Debug.Log("[GameManager] Game paused.");
    }

    public void ResumeGame()
    {
        if (!IsGamePaused) return;
        IsGamePaused = false;
        Time.timeScale = 1f;
        // Additional resume logic here
        Debug.Log("[GameManager] Game resumed.");
    }
}

